    components=new QLabel;components->setObjectName("imageComponents");components->setWordWrap(true);components->setTextFormat(Qt::PlainText);settingsLayout->addWidget(components);auto check=new StudioButton("Проверить компоненты");settingsLayout->addWidget(check);connect(check,&QPushButton::clicked,this,[this]{validate();});
