    auto logTools=new QHBoxLayout;auto saveLog=new StudioButton("Сохранить журнал…");auto clear=new StudioButton("Очистить");logTools->addWidget(saveLog);logTools->addWidget(clear);logTools->addStretch();logsLayout->addLayout(logTools);console=new QPlainTextEdit;console->setObjectName("imageConsole");console->setReadOnly(true);console->setMaximumBlockCount(10000);logsLayout->addWidget(console,1);tabs->addTab(logsTab,"Сервер · журнал");
    state=new QLabel;state->setObjectName("imageStatus");state->setTextFormat(Qt::PlainText);state->setWordWrap(true);layout->addWidget(state);auto actions=new QHBoxLayout;auto monitor=new StudioButton("Мониторинг");actions->addWidget(monitor);actions->addStretch();openButton=new StudioButton("Открыть Web UI");openButton->setObjectName("imageOpenWeb");stopButton=new StudioButton("Остановить");stopButton->setObjectName("imageStop");startButton=new StudioButton("▶ Запустить sd-server");startButton->setObjectName("imageStart");actions->addWidget(openButton);actions->addWidget(stopButton);actions->addWidget(startButton);layout->addLayout(actions);
