void ImagePage::loadSettings(const QJsonObject &json) {
    if(runner.busy())return;loading=true;configuration=ImageSettings::fromJson(json);root->setText(configuration.rootDirectory);executable->setText(configuration.executablePath);models->setText(configuration.modelDirectory);host->setText(configuration.listenIp);port->setValue(configuration.port);profiles->clear();for(auto value:configuration.profiles){auto p=value.toObject();profiles->addItem(p.value("name").toString(),p.value("id").toString());}profiles->setCurrentIndex(profiles->findData(configuration.selectedProfile));loading=false;showProfile();state->setText(runner.status());
}
void ImagePage::showProfile() {
    loading=true;const auto p=configuration.profile();note->setText(p.value("note").toString());autoFit->setCurrentIndex(qMax(0,autoFit->findData(p.value("autoFit").toString())));mode->setCurrentIndex(mode->findData(p.value("modelMode").toString()));for(auto it=texts.begin();it!=texts.end();++it)it.value()->setText(p.value(it.key()).toVariant().toString());for(auto it=integers.begin();it!=integers.end();++it)it.value()->setValue(p.value(it.key()).toInt());cfg->setValue(p.value("cfgScale").toDouble());sampler->setCurrentText(p.value("samplingMethod").toString());offload->setChecked(p.value("offloadToCpu").toBool());tiling->setChecked(p.value("vaeTiling").toBool());extras->setPlainText(p.value("extraArguments").isArray()?QString::fromUtf8(QJsonDocument(p.value("extraArguments").toArray()).toJson(QJsonDocument::Compact)):p.value("extraArguments").toVariant().toString());loading=false;const auto problems=configuration.componentProblems();components->setText(problems.isEmpty()?"Файлы присутствуют; размеры компонентов сверены с assets.json, если он есть. SHA256 сверяйте с источником; совместимость проверяйте пробной генерацией.":problems.join('\n'));refresh();
}
void ImagePage::edited() {
    if(loading||runner.busy())return;configuration.rootDirectory=root->text().trimmed();configuration.executablePath=executable->text().trimmed();configuration.modelDirectory=models->text().trimmed();configuration.listenIp=host->text().trimmed();configuration.port=port->value();auto p=configuration.profile();if(!p.isEmpty()){
        p["modelMode"]=mode->currentData().toString();p["autoFit"]=autoFit->currentData().toString();for(auto it=texts.begin();it!=texts.end();++it)p[it.key()]=it.value()->text().trimmed();for(auto it=integers.begin();it!=integers.end();++it)p[it.key()]=it.value()->value();p["cfgScale"]=cfg->value();p["samplingMethod"]=sampler->currentText().trimmed();p["offloadToCpu"]=offload->isChecked();p["vaeTiling"]=tiling->isChecked();const auto doc=QJsonDocument::fromJson(extras->toPlainText().toUtf8());p["extraArguments"]=doc.isArray()?QJsonValue(doc.array()):QJsonValue(extras->toPlainText());for(int i=0;i<configuration.profiles.size();++i)if(configuration.profiles[i].toObject().value("id").toString()==configuration.selectedProfile)configuration.profiles[i]=p;
    }components->setText("Настройки изменены. Нажмите «Проверить компоненты»; при запуске проверка выполняется повторно.");emit settingsChanged(configuration.toJson());refresh();
}
void ImagePage::setBlocked(bool value){blocked=value;refresh();}
void ImagePage::refresh() {
    fields->setEnabled(!runner.busy()&&!blocked);startButton->setEnabled(!runner.busy()&&!blocked);stopButton->setEnabled(runner.busy());openButton->setEnabled(runner.webAvailable());QString executable,error;QStringList args;QUrl url;preview->setPlainText(configuration.command(&executable,&args,&url,&error,false)?Config::displayCommand(executable,args,false):error);
}
bool ImagePage::validate(){QString executable,error;QStringList args;QUrl url;const auto ok=configuration.command(&executable,&args,&url,&error);components->setText(ok?"Компоненты присутствуют. Проверка наличия и размера не заменяет SHA256 и пробную генерацию.":error);if(!ok){state->setText("Запуск невозможен: проверьте компоненты и параметры.");tabs->setCurrentIndex(0);}return ok;}
void ImagePage::start(){if(blocked||!validate())return;QString error;if(!runner.start(configuration,&error)){state->setText(error);append("\n["+error+"]\n");return;}actual->setPlainText(runner.commandText());tabs->setCurrentIndex(1);refresh();}
void ImagePage::append(const QString &text){auto cursor=console->textCursor();cursor.movePosition(QTextCursor::End);cursor.insertText(text);console->setTextCursor(cursor);console->ensureCursorVisible();}
